function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Test a plugin-supplied pattern without inheriting its `lastIndex`. */
function testPattern(pattern, value) {
  pattern.lastIndex = 0;
  return pattern.test(value);
}

