function appendChordSuffix(displayRoot, suffix) {
  return displayRoot
    .split('/')
    .map((variant) => `${variant.trim()}${suffix}`)
    .join(' / ');
}

function createChordKeyGroup(name, roots, suffix) {
  return {
    name,
    keys: roots.map((root) => appendChordSuffix(root, suffix)),
  };
}

