function hasChordProgressionText(value, allowZeroWidthSpace = true) {
  const source = String(value ?? '');
  if (!source.includes('|')) {
    return false;
  }

  return source
    .replace(/(\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\||\([1-9]\d*x\))/g, ' ')
    .split(allowZeroWidthSpace ? /[\s\u200B]+/u : /\s+/)
    .some((segment) => BARE_CHORD_RE.test(segment));
}

