syncEditorActivityState();
syncEditorDirtyState();

function parseSharedDocumentDateValue(value) {
  const normalizedValue = String(value ?? '').trim();

  if (!normalizedValue) {
    return null;
  }

  const match = normalizedValue.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T_\s])(\d{2})[-:](\d{2})[-:](\d{2})$/,
  );

  if (match) {
    const [, yearText, monthText, dayText, hourText, minuteText, secondText] =
      match;
    const year = Number.parseInt(yearText, 10);
    const month = Number.parseInt(monthText, 10);
    const day = Number.parseInt(dayText, 10);
    const hour = Number.parseInt(hourText, 10);
    const minute = Number.parseInt(minuteText, 10);
    const second = Number.parseInt(secondText, 10);
    const parsedDate = new Date(year, month - 1, day, hour, minute, second);

    if (
      parsedDate.getFullYear() === year &&
      parsedDate.getMonth() === month - 1 &&
      parsedDate.getDate() === day &&
      parsedDate.getHours() === hour &&
      parsedDate.getMinutes() === minute &&
      parsedDate.getSeconds() === second
    ) {
      return parsedDate;
    }

    return null;
  }

  const timestamp = Date.parse(normalizedValue);

  if (!Number.isFinite(timestamp)) {
    return null;
  }

  const parsedDate = new Date(timestamp);
  return Number.isNaN(parsedDate.getTime()) ? null : parsedDate;
}

function formatSharedDocumentDateValue(value, options) {
  const parsedDate = parseSharedDocumentDateValue(value);

  if (!parsedDate) {
    return '';
  }

  return new Intl.DateTimeFormat(undefined, options).format(parsedDate);
}

function setSharedDocumentDate(value) {
  const normalizedValue = String(value ?? '').trim();
  const shortLabel = formatSharedDocumentDateValue(normalizedValue, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });

  state.sharedDocumentDate = shortLabel ? normalizedValue : '';

  if (!refs.sharedDocumentDate) {
    return;
  }

  if (!shortLabel) {
    refs.sharedDocumentDate.hidden = true;
    refs.sharedDocumentDate.textContent = '';
    refs.sharedDocumentDate.title = '';
    refs.sharedDocumentDate.removeAttribute('aria-label');
    return;
  }

  const fullLabel = formatSharedDocumentDateValue(normalizedValue, {
    dateStyle: 'full',
    timeStyle: 'medium',
  });

  refs.sharedDocumentDate.hidden = false;
  refs.sharedDocumentDate.textContent = `Shared edit: ${shortLabel}`;
  refs.sharedDocumentDate.title = `Last shared edit: ${fullLabel}`;
  refs.sharedDocumentDate.setAttribute(
    'aria-label',
    `Last shared edit: ${fullLabel}`,
  );
}

function setStatus(message) {
  if (refs.status) {
    refs.status.textContent = message;
  }
}

function supportsLegacyClipboardCopy() {
  if (typeof document.execCommand !== 'function') {
    return false;
  }

  if (typeof document.queryCommandSupported === 'function') {
    try {
      return document.queryCommandSupported('copy');
    } catch (_error) {
      // Fall back to the presence of execCommand below.
    }
  }

  return true;
}

function supportsLegacyClipboardPaste() {
  if (
    typeof document.execCommand !== 'function' ||
    typeof document.queryCommandSupported !== 'function'
  ) {
    return false;
  }

  try {
    return document.queryCommandSupported('paste');
  } catch (_error) {
    return false;
  }
}

function supportsClipboardCopy() {
  return (
    typeof globalThis.navigator?.clipboard?.writeText === 'function' ||
    supportsLegacyClipboardCopy()
  );
}

function supportsClipboardPaste() {
  return (
    typeof globalThis.navigator?.clipboard?.readText === 'function' ||
    supportsLegacyClipboardPaste()
  );
}

function syncEditorActivityState() {
  if (!(refs.editorPanel instanceof HTMLElement)) {
    return;
  }

  refs.editorPanel.dataset.activityState =
    runtime.editorActivityCount > 0 ? 'busy' : 'idle';
}

function startEditorActivity() {
  runtime.editorActivityCount += 1;
  syncEditorActivityState();

  let finished = false;

  return () => {
    if (finished) {
      return;
    }

    finished = true;
    runtime.editorActivityCount = Math.max(0, runtime.editorActivityCount - 1);
    syncEditorActivityState();
  };
}

// How long the unsaved-changes toast stays up after an unload attempt. Long
// enough to read once the native "Leave site?" dialog is dismissed — the toast
// is queued behind it, so the user only really sees it if they chose "Cancel".
const UNSAVED_CHANGES_TOAST_MS = 8000;

// The guard's escape hatch: it blocks this many attempts in a row and lets the
// next one through, so a reader who genuinely wants to leave is never stuck
// behind a dialog they cannot satisfy (the draft survives in browser storage
// either way). The streak has to be deliberate — it lapses this long after the
// last attempt, so an accidental reload weeks apart never adds up.
const BLOCKED_UNLOAD_ATTEMPTS = 3;
const UNLOAD_ATTEMPT_RESET_MS = 2000;

/**
 * Mirror the unsaved-changes flag onto the editor panel as `data-dirty`, which
 * is what paints the panel's red top border (`styles/shell.scss`), and onto
 * the editor tools menu's document group, whose Reset and Save buttons are
 * enabled only while there is something to discard or write.
 *
 * It tracks `state.dirty` exactly, so both markers mean the same condition the
 * unload guard prompts on — see
 * `OpenLyricEditorApplication.handleWindowBeforeUnload`. "Dirty" here means
 * *not written to disk*: every keystroke still autosaves the draft to browser
 * storage, so a reload restores the text either way.
 */
function syncEditorDirtyState() {
  if (refs.editorPanel instanceof HTMLElement) {
    refs.editorPanel.dataset.dirty = state.dirty ? 'true' : 'false';
  }

  for (const button of [
    refs.editorResetBtn,
    refs.editorSaveBtn,
    refs.topbarResetBtn,
    refs.topbarSaveBtn,
  ]) {
    if (button instanceof HTMLButtonElement) {
      button.disabled = !state.dirty;
    }
  }
}

/**
 * Count one unload attempt and report how many more the guard will block.
 *
 * `0` means "let this one through" — the caller must not cancel the event.
 * The streak lapses `UNLOAD_ATTEMPT_RESET_MS` after the last attempt; the
 * timer only starts ticking once the native dialog is dismissed, because the
 * dialog blocks the renderer's event loop, so the window is measured from the
 * user's answer rather than from the keypress.
 */
function registerUnloadAttempt() {
  runtime.unloadAttemptCount += 1;

  if (runtime.unloadAttemptResetTimer) {
    clearTimeout(runtime.unloadAttemptResetTimer);
  }

  runtime.unloadAttemptResetTimer = setTimeout(
    resetUnloadAttempts,
    UNLOAD_ATTEMPT_RESET_MS,
  );

  return Math.max(0, BLOCKED_UNLOAD_ATTEMPTS + 1 - runtime.unloadAttemptCount);
}

/**
 * Drop the unload streak — on the reset timer, and whenever the document
 * stops being dirty (a save answers the question the streak was asking).
 */
function resetUnloadAttempts() {
  if (runtime.unloadAttemptResetTimer) {
    clearTimeout(runtime.unloadAttemptResetTimer);
    runtime.unloadAttemptResetTimer = 0;
  }

  runtime.unloadAttemptCount = 0;
  syncUnsavedChangesToastAttempts(BLOCKED_UNLOAD_ATTEMPTS);
}

/**
 * Write the "how to leave anyway" line, so a toast still on screen when the
 * streak lapses re-states the full count instead of a stale remainder.
 */
function syncUnsavedChangesToastAttempts(remainingAttempts) {
  if (!(refs.unsavedChangesToastAttempts instanceof HTMLElement)) {
    return;
  }

  refs.unsavedChangesToastAttempts.textContent =
    remainingAttempts === 1
      ? 'Reload once more to leave without saving.'
      : `Reload ${remainingAttempts} more times in a row to leave without saving.`;
}

/**
 * Show the unsaved-changes toast for an unload attempt.
 *
 * A `beforeunload` handler cannot put its own wording in the browser's dialog
 * — that text is fixed by the browser — so this is the only way to explain
 * *why* the reload was interrupted, and the only place the escape hatch can be
 * advertised. It paints behind the native dialog and stays up afterwards,
 * which is what the user sees when they cancel.
 */
function showUnsavedChangesToast(remainingAttempts = BLOCKED_UNLOAD_ATTEMPTS) {
  if (!(refs.unsavedChangesToast instanceof HTMLElement)) {
    return;
  }

  if (runtime.unsavedChangesToastTimer) {
    clearTimeout(runtime.unsavedChangesToastTimer);
  }

  syncUnsavedChangesToastAttempts(remainingAttempts);
  refs.unsavedChangesToast.hidden = false;
  runtime.unsavedChangesToastTimer = setTimeout(
    hideUnsavedChangesToast,
    UNSAVED_CHANGES_TOAST_MS,
  );
}

function hideUnsavedChangesToast() {
  if (runtime.unsavedChangesToastTimer) {
    clearTimeout(runtime.unsavedChangesToastTimer);
    runtime.unsavedChangesToastTimer = 0;
  }

  if (refs.unsavedChangesToast instanceof HTMLElement) {
    refs.unsavedChangesToast.hidden = true;
  }
}

function updateStatus() {
  const dirtyMark = state.dirty ? ' *' : '';
  const errorText = state.errorCount
    ? ` · ${state.errorCount} lexical ${state.errorCount === 1 ? 'error' : 'errors'}`
    : '';

  setStatus(`${state.fileName}${dirtyMark}${errorText}`);
}

function setErrorCount(nextErrorCount) {
  state.errorCount = nextErrorCount;
  updateStatus();
}

function getCurrentValue() {
  if (
    state.editorMode === 'simple' &&
    refs.simpleEditorTextarea instanceof HTMLTextAreaElement
  ) {
    return refs.simpleEditorTextarea.value;
  }

  return state.editor ? state.editor.getValue() : state.currentDocumentContent;
}

function setCurrentDocumentContent(value) {
  state.currentDocumentContent = String(value ?? '');
}

function setSimpleEditorValue(value) {
  if (!(refs.simpleEditorTextarea instanceof HTMLTextAreaElement)) {
    return;
  }

  refs.simpleEditorTextarea.value = String(value ?? '');
}

function markDirty(nextDirty) {
  state.dirty = nextDirty;

  if (!nextDirty) {
    // Clean means "what is on screen IS the saved document", so every caller
    // that clears the flag — boot, an explicit save, a load/reset through
    // `applyDocumentContent` — is also the moment the revert baseline is
    // current. Capturing it here rather than at each call site keeps the two
    // in step by construction.
    state.lastSavedContent = String(getCurrentValue() ?? '');
  }

  syncEditorDirtyState();

  if (!nextDirty) {
    hideUnsavedChangesToast();
    resetUnloadAttempts();
  }

  updateStatus();
}

function setDropActive(active) {
  if (refs.app) {
    refs.app.classList.toggle('drop-active', active);
  }
}

