import example1Content from '../../plugins/OpenLyric/examples/example1.md?raw';
import { DEFAULT_EDITOR_ONLY_DRAFT_EXAMPLE } from './editor-only-draft-examples.ts';
import {
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
  getEditorShellMode,
} from './page-config.ts';

const DEFAULT_FULL_DRAFT_EXAMPLE = {
  id: 'open_lyric_ol_editor:example1',
  fileName: 'example1.md',
  title: 'Extended Worship Build',
  description:
    'Extended worship flow with multiple bridges, instrumentals, repeat counts, and a final chorus.',
  content: example1Content,
  editorShellModes: [FULL_EDITOR_SHELL_MODE],
};

function getDefaultDraftExample() {
  return getEditorShellMode() === EDITOR_ONLY_SHELL_MODE
    ? DEFAULT_EDITOR_ONLY_DRAFT_EXAMPLE
    : DEFAULT_FULL_DRAFT_EXAMPLE;
}

const DEFAULT_DRAFT_EXAMPLE = getDefaultDraftExample();

export {
  DEFAULT_DRAFT_EXAMPLE,
  DEFAULT_FULL_DRAFT_EXAMPLE,
  getDefaultDraftExample,
};
