const OPEN_LYRIC_PLUGIN_ENABLED_STORAGE_KEY =
  'open-lyric-editor-plugin-open-lyric';

function getBrowserStorage(storageName) {
  try {
    return globalThis[storageName] ?? null;
  } catch (_error) {
    return null;
  }
}

function normalizeOpenLyricPluginEnabledPreference(value) {
  return value !== false;
}

function loadOpenLyricPluginEnabledPreference(
  storage = getBrowserStorage('localStorage'),
) {
  try {
    const storedValue = storage?.getItem(OPEN_LYRIC_PLUGIN_ENABLED_STORAGE_KEY);

    if (storedValue === '1' || storedValue === '0') {
      return storedValue === '1';
    }
  } catch (_error) {
    // Ignore storage failures.
  }

  return true;
}

function saveOpenLyricPluginEnabledPreference(
  enabled,
  storage = getBrowserStorage('localStorage'),
) {
  try {
    storage?.setItem(
      OPEN_LYRIC_PLUGIN_ENABLED_STORAGE_KEY,
      normalizeOpenLyricPluginEnabledPreference(enabled) ? '1' : '0',
    );
  } catch (_error) {
    // Ignore storage failures.
  }
}

export {
  OPEN_LYRIC_PLUGIN_ENABLED_STORAGE_KEY,
  loadOpenLyricPluginEnabledPreference,
  normalizeOpenLyricPluginEnabledPreference,
  saveOpenLyricPluginEnabledPreference,
};
