import { OLFenceDefinition } from './OLFenceDefinition.ts';

class OLInstrumentalFence extends OLFenceDefinition {
  constructor(options) {
    super({
      ...options,
      kind: 'instrumental',
      tokenState: 'olInstrumental',
    });
  }

  validateBody(context) {
    context.validators.validateDirectiveBlock(
      context.bodyLines,
      context.startLineNumber,
      context.markers,
      this.header,
      context.directivePatterns.instrumental,
      '{c: Piano + Pads }',
    );
  }

  renderPreviewBody(context) {
    return context.helpers.renderChordProgressionLineCollection(
      context.lineEntries,
    );
  }
}

export { OLInstrumentalFence };
